using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text;

static class ChallengeBank {
 public static readonly string[] Chapters={"微光初醒","星屑阵列","符文回廊","星轨推演","深空试炼"};
 public static readonly List<ChallengeLevel> Levels=Build();
 static string C(string body){return "#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n#include <limits.h>\n\nint main(void)\n{\n"+body+"\n    return 0;\n}\n";}
 static ChallengeLevel L(int n,string title,string statement,string concepts,string steps,string pitfalls,string body){return new ChallengeLevel{Number=n,Problem=new Problem(100+n,title,"暗域 · "+Chapters[(n-1)/10],statement,"先阅读本关详细学习提示，再独立编写。",C(body)),Learning=Lesson(n,concepts,steps,pitfalls)};}
 static string Lesson(int n,string concepts,string steps,string pitfalls){return "第 "+n.ToString("00")+" 关 · 学习与拆解\n\n学习目标\n"+concepts+"\n\n动手前准备\n先读清输入顺序、数据范围、输出格式，用纸笔完成题目示例。输入中的空格与换行通常都可由scanf处理，输出不要添加额外提示。变量先初始化，数组下标必须在范围内。\n\n分步提示\n"+steps+"\n\n常见错误与边界\n"+pitfalls+"\n\n建议的练习顺序\n①先写读取输入，确认变量类型与格式符对应；②用小数据手算中间值，再写循环或状态更新；③完成输出后，检查最小规模、重复值和边界情况；④提交后对照输入、实际输出和预期输出，定位第一次分歧。\n\n可先在普通练习中复习相关语法。阅读提示不消耗尝试次数；开始挑战后阅读仍会计时。算法提示开放，完整答案在本关通关后用于复盘；请从空白自主编写。";}
 static List<ChallengeLevel> Build(){var a=new List<ChallengeLevel>{
 L(1,"微光采集 · 数位和","输入非负整数 n（0≤n≤10亿），输出它的十进制各位数字之和。","复习普通练习30～40题涉及的循环、整数除法与取余。只需单个循环。","1. 用sum保存累计和，从0开始。\n2. n%10取个位，加入sum。\n3. n/10去掉个位，反复处理，直到n变成0。\n4. 输入0时不必进入循环，结果仍为0。","不要用n/10取个位；n在处理时会改变，不需要保存原值。本题最大和不超过90，int足够。","    int n,s=0;scanf(\"%d\",&n);while(n>0){s+=n%10;n/=10;}printf(\"%d\\n\",s);"),
 L(2,"奇偶星粒","输入非负整数 n（0≤n≤10亿），依次输出十进制奇数位数字的个数和偶数位数字的个数。这里按数字值判断奇偶，不按所在位置；n=0视为一位偶数字。","在逐位循环中加入if分支，学会处理必须执行一次的循环。","1. 准备odd、even两个计数器。\n2. 至少取出一位，用(n%10)%2判断该位数字。\n3. 对应计数器加1，再删去个位。\n4. 可使用do…while保证0也处理一次。","不要混淆第几位与该位的值。比如120有1个奇数字和2个偶数字；输入0输出0 1。","    int n,o=0,e=0;scanf(\"%d\",&n);do{if((n%10)%2)o++;else e++;n/=10;}while(n);printf(\"%d %d\\n\",o,e);"),
 L(3,"因子回响","输入整数 n（1≤n≤10000），输出 n 的所有正因子之和。","用循环枚举候选数，以余数为0判断整除。","1. 从1到n枚举d。\n2. n%d==0时把d计入总和。\n3. 本题范围小，直接枚举即可，不要求复杂算法。\n4. 用n=6手算1+2+3+6验证。","1和n本身都要计入。n=1时只有因子1，不要重复加两次。","    int n,s=0;scanf(\"%d\",&n);for(int d=1;d<=n;d++)if(n%d==0)s+=d;printf(\"%d\\n\",s);"),
 L(4,"群星筛选","输入 n（1≤n≤1000），输出1到n之间的质数个数。","在外层枚举与内层试除中练习标记变量和break。","1. 从2开始枚举x，默认认为它是质数。\n2. 枚举2到平方根的可能因子。\n3. 若整除，修改标记并退出试除。\n4. 只有标记仍成立时才增加计数。","1不是质数；试除条件d*d<=x必须含等号，否则4、9等平方数可能判断错误。","    int n,c=0;scanf(\"%d\",&n);for(int x=2;x<=n;x++){int ok=1;for(int d=2;d*d<=x;d++)if(x%d==0){ok=0;break;}c+=ok;}printf(\"%d\\n\",c);"),
 L(5,"二进星火","输入非负整数 n（0≤n≤65535），输出它的二进制表示中1的数量。","把十进制逐位处理的方法迁移到二进制，理解除2和模2。","1. n%2得到最低二进制位。\n2. 把该位加到计数中。\n3. n/=2继续处理下一位。\n4. 也可探索n&1与右移，但本题不强制使用。","不要统计十进制的字符1。n=0结果为0；n=7的二进制是111，结果为3。","    int n,c=0;scanf(\"%d\",&n);while(n){c+=n%2;n/=2;}printf(\"%d\\n\",c);"),
 L(6,"双星周期","输入两个正整数 a b（各1～10000），输出最大公约数与最小公倍数，按此顺序输出。","学习辗转相除，并把一个计算结果用于第二个结果。","1. 保留原始a、b，另用x、y循环。\n2. 每次计算r=x%y，再令x=y、y=r。\n3. y为0时x就是最大公约数g。\n4. 最小公倍数可以用(a/g)*b求得。","不要把循环后已改变的y当成原始b。先除再乘可减小中间数。","    int a,b,x,y;scanf(\"%d%d\",&a,&b);x=a;y=b;while(y){int r=x%y;x=y;y=r;}printf(\"%d %d\\n\",x,a/x*b);"),
 L(7,"镜中星码","输入非负整数 n（0≤n≤1000000），若其十进制表示是回文，输出YES，否则输出NO。","保留原值，利用取余与累乘构造反转数字。","1. 保存original，再复制一个x用于处理。\n2. 反转值rev从0开始。\n3. 每次令rev=rev*10+x%10，再删除x个位。\n4. 比较rev与original。","末尾0在反转后不会保留，例如10不是回文；0和所有一位数都是回文。","    int n,x,r=0;scanf(\"%d\",&n);x=n;while(x){r=r*10+x%10;x/=10;}puts(r==n?\"YES\":\"NO\");"),
 L(8,"星区巡查","输入 l r（1≤l≤r≤500），输出闭区间内质数的数量与这些质数之和。","将质数判断放入区间扫描，维护数量和总和两类结果。","1. 枚举闭区间内的每个x。\n2. 单独排除x<2，再试除到平方根。\n3. 是质数时同时更新count与sum。\n4. 两个结果用一个空格分隔。","闭区间必须含r；没有质数时输出0 0，不能漏掉总和。","    int l,r,c=0,s=0;scanf(\"%d%d\",&l,&r);for(int x=l;x<=r;x++){int ok=x>=2;for(int d=2;d*d<=x;d++)if(x%d==0){ok=0;break;}if(ok){c++;s+=x;}}printf(\"%d %d\\n\",c,s);"),
 L(9,"生长星链","定义F1=1、F2=1、Fk=F(k-1)+F(k-2)。输入n（1≤n≤40），输出F1到Fn之和。","练习用两个变量保存递推状态，并用long long累计。","1. 可用a=0、b=1代表相邻两项。\n2. 循环n次，每次先把b计入总和。\n3. 保存a+b，再把a更新为b、b更新为新值。\n4. n=1、2时应分别得到1、2。","更新顺序会影响计算，使用临时变量。long long输出用%lld。","    int n;long long a=0,b=1,s=0;scanf(\"%d\",&n);for(int i=0;i<n;i++){s+=b;long long t=a+b;a=b;b=t;}printf(\"%lld\\n\",s);"),
 L(10,"微光观测站","输入 l r（1≤l≤r≤500）。输出三个整数：闭区间内质数个数、完全平方数个数、所有奇数之和。","综合多种判断条件，在一次区间扫描中独立维护不同指标。","1. 为三项结果分别初始化变量。\n2. 每个x试除判断质数。\n3. 可枚举d检查d*d==x判断平方数。\n4. x%2不为0时计入奇数和，三种条件可以同时成立。","不要使用互斥else if：同一个数可能被多个统计项计入。1是平方数和奇数，但不是质数。","    int l,r,p=0,q=0,s=0;scanf(\"%d%d\",&l,&r);for(int x=l;x<=r;x++){int ok=x>=2;for(int d=2;d*d<=x;d++)if(x%d==0)ok=0;p+=ok;for(int d=1;d*d<=x;d++)if(d*d==x)q++;if(x%2)s+=x;}printf(\"%d %d %d\\n\",p,q,s);"),
 L(11,"星屑测量","输入n（1～50），随后n个整数（-1000～1000）。依次输出最小值、最大值、总和。","从单个数过渡到一维数组或逐个读取，学习正确初始化极值。","1. 读取第一项作为min和max初值。\n2. 逐项更新较小值、较大值并累加。\n3. 总和可以在读取时计算，无须保存全部数组。","不能把min或max固定设为0，否则全正或全负数会出错。n=1时最小值和最大值相同。","    int n,x,lo=1001,hi=-1001,s=0;scanf(\"%d\",&n);while(n--){scanf(\"%d\",&x);if(x<lo)lo=x;if(x>hi)hi=x;s+=x;}printf(\"%d %d %d\\n\",lo,hi,s);"),
 L(12,"定位星标","输入n（1～50）与n个整数（-1000～1000）。输出最小值首次出现的位置和最大值首次出现的位置；位置从1开始。","同时保存值与对应下标，区分首次出现和最后出现。","1. 用第一个元素初始化两个位置。\n2. 扫描余下元素。\n3. 只有严格更小或更大才更新位置，相等时保留原位置。","数组从0编号时，输出位置需加1。使用<=或>=可能得到最后一次出现的位置。","    int n,a[50],lo=0,hi=0;scanf(\"%d\",&n);for(int i=0;i<n;i++){scanf(\"%d\",a+i);if(a[i]<a[lo])lo=i;if(a[i]>a[hi])hi=i;}printf(\"%d %d\\n\",lo+1,hi+1);"),
 L(13,"逆行星尘","输入n（1～50）和n个整数（-1000～1000），按原顺序的逆序输出这n项。","保存数组后反向遍历，理解n-1是最后一个合法下标。","1. 按输入顺序存入a[0..n-1]。\n2. 从i=n-1递减到0。\n3. 每输出一项后用空格分隔，最后换行。","不能从a[n]开始；n=1时仍输出唯一元素。不要遗漏下标0。","    int n,a[50];scanf(\"%d\",&n);for(int i=0;i<n;i++)scanf(\"%d\",a+i);for(int i=n-1;i>=0;i--)printf(\"%d%c\",a[i],i?' ':'\\n');"),
 L(14,"奇偶双轨","输入n（1～50）和n个整数（-1000～1000）。先输出所有奇数，再输出所有偶数；两组内部保持原输入顺序，输出一行。","通过两次扫描完成稳定分类，练习负数的奇偶判断。","1. 先保存数组。\n2. 第一次扫描输出a[i]%2!=0的元素。\n3. 第二次输出a[i]%2==0的元素。\n4. 用first标记控制项之间的空格。","负奇数取余可能为-1，所以不能仅判断余数==1。分类不能随意交换元素破坏内部顺序。","    int n,a[50],first=1;scanf(\"%d\",&n);for(int i=0;i<n;i++)scanf(\"%d\",a+i);for(int k=0;k<2;k++)for(int i=0;i<n;i++)if((a[i]%2!=0)==(k==0)){if(!first)putchar(' ');printf(\"%d\",a[i]);first=0;}putchar('\\n');"),
 L(15,"次亮星辰","输入n（1～50）和n个整数（-1000～1000）。输出第二大的不同值；若只有一种值，输出NONE。","分清第二个元素与第二大的不同值，用两次扫描简化逻辑。","1. 第一遍找最大值。\n2. 第二遍只考虑小于最大值的元素，取其中最大者。\n3. 若第二遍无候选值，输出NONE。","例如5 5 3的结果是3；全相同时无结果。哨兵应小于题目最小值。","    int n,a[50],hi=-1001,b=-1001;scanf(\"%d\",&n);for(int i=0;i<n;i++){scanf(\"%d\",a+i);if(a[i]>hi)hi=a[i];}for(int i=0;i<n;i++)if(a[i]<hi&&a[i]>b)b=a[i];if(b==-1001)puts(\"NONE\");else printf(\"%d\\n\",b);"),
 L(16,"有序星簇","输入n（1～50）和n个整数（-1000～1000）。第一行输出不同值的数量，第二行按升序输出这些不同值。","练习简单排序，再通过相邻元素比较去重。","1. 用冒泡或选择排序得到非递减数组。\n2. 第一项保留，之后仅保留与前一项不同的值。\n3. 可以先压缩到数组前部，再输出数量和内容。","排序时避免访问a[n]；不能直接在未排序数组中仅比较相邻项来去重。","    int n,a[50],m=0;scanf(\"%d\",&n);for(int i=0;i<n;i++)scanf(\"%d\",a+i);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(a[j]<a[i]){int t=a[i];a[i]=a[j];a[j]=t;}for(int i=0;i<n;i++)if(i==0||a[i]!=a[i-1])a[m++]=a[i];printf(\"%d\\n\",m);for(int i=0;i<m;i++)printf(\"%d%c\",a[i],i==m-1?'\\n':' ');"),
 L(17,"搜寻坐标","输入n与目标x（1≤n≤50，-1000≤x≤1000），随后n个整数（-1000～1000）。输出x首次出现的1基位置与出现次数；不存在时输出0 0。","把查找位置和频次统计放在同一次扫描中。","1. 位置与计数都初始化为0。\n2. 遇到目标值就增加次数。\n3. 仅当位置仍为0时记录当前的1基位置。","找到首次位置后仍需继续扫描，不能break，否则次数不完整。","    int n,x,v,at=0,c=0;scanf(\"%d%d\",&n,&x);for(int i=1;i<=n;i++){scanf(\"%d\",&v);if(v==x){c++;if(!at)at=i;}}printf(\"%d %d\\n\",at,c);"),
 L(18,"旋转星盘","输入n k（1≤n≤50，0≤k≤1000），随后n个整数（-1000～1000）。将数组循环右移k位，输出结果。","用取模把旋转后的访问位置映射回原数组。","1. 先令k=k%n，消除整圈旋转。\n2. 输出位置i原本来自(i+n-k)%n。\n3. 从i=0到n-1按顺序输出。","右移和左移方向相反；加n后再取模可以避免负下标。k=0或k是n的倍数时原样输出。","    int n,k,a[50];scanf(\"%d%d\",&n,&k);k%=n;for(int i=0;i<n;i++)scanf(\"%d\",a+i);for(int i=0;i<n;i++)printf(\"%d%c\",a[(i+n-k)%n],i==n-1?'\\n':' ');"),
 L(19,"星带查询","输入n q（1≤n≤50，1≤q≤12），随后n个整数（-1000～1000），再输入q对l r（1≤l≤r≤n）。每行输出闭区间[l,r]的和。","处理多次查询，分清输入坐标与数组下标。","1. 读入完整数组。\n2. 每次查询将l、r转换到0基下标。\n3. 在区间内直接循环求和即可；数据规模允许。\n4. 学有余力时再尝试前缀和。","每次查询的sum都应重置为0。l=r只包含一个元素，不能漏算右端点。","    int n,q,a[50];scanf(\"%d%d\",&n,&q);for(int i=0;i<n;i++)scanf(\"%d\",a+i);while(q--){int l,r,s=0;scanf(\"%d%d\",&l,&r);for(int i=l-1;i<r;i++)s+=a[i];printf(\"%d\\n\",s);}"),
 L(20,"星阵终端","输入n q（1≤n≤50，1≤q≤20），随后n个整数（-1000～1000）。后有q条命令：S i v将第i项设为v（-1000～1000）不输出；Q i查询并输出第i项；i从1开始。","把数组当作持续变化的状态，学习读取字符命令及分支。","1. 初始化数组后循环读取q条命令。\n2. 用scanf的空白前缀跳过上一行留下的换行。\n3. 按S或Q读取不同数量参数。\n4. 更新必须影响后续查询。","读取命令建议使用scanf(\" %c\",&op)。查询不改变状态；S命令不要输出多余文字。","    int n,q,a[51];scanf(\"%d%d\",&n,&q);for(int i=1;i<=n;i++)scanf(\"%d\",a+i);while(q--){char op;int i,v;scanf(\" %c%d\",&op,&i);if(op=='S'){scanf(\"%d\",&v);a[i]=v;}else printf(\"%d\\n\",a[i]);}"),
 L(21,"符文分类","输入一个不含空白的可见ASCII字符串（长度1～100），依次输出大写字母、小写字母、数字、其他字符的数量。","从整数数组过渡到char数组，以字符范围比较完成分类。","1. 缓冲区至少101字节，为结束符留位置。\n2. 遍历到'\\0'结束。\n3. 用'A'到'Z'等范围判断，最后一类收集剩余字符。","字符范围比较要写成c>='A'&&c<='Z'；C不支持把数学中的连写比较直接照搬。","    char s[101];int u=0,l=0,d=0,o=0;scanf(\"%100s\",s);for(int i=0;s[i];i++){char c=s[i];if(c>='A'&&c<='Z')u++;else if(c>='a'&&c<='z')l++;else if(c>='0'&&c<='9')d++;else o++;}printf(\"%d %d %d %d\\n\",u,l,d,o);"),
 L(22,"连续铭文","输入长度1～100的小写字符串。将每段连续相同字符输出为字符加十进制次数，各段紧接；如aaabb输出a3b2。","学习按连续段分组扫描，而不是统计全局频率。","1. i指向当前段起点。\n2. j从i开始向右寻找第一个不同字符或结尾。\n3. 段长为j-i，输出s[i]及段长。\n4. i移到j，继续下一段。","末尾一段也要输出；aba应输出a1b1a1，而非a2b1。次数可超过9。","    char s[101];scanf(\"%100s\",s);for(int i=0;s[i];){int j=i+1;while(s[j]&&s[j]==s[i])j++;printf(\"%c%d\",s[i],j-i);i=j;}putchar('\\n');"),
 L(23,"符文替换","输入一个长度1～100、只含数字和英文字母的字符串，再输入两个字符a b（同样是数字或英文字母）。把字符串中所有a替换为b，输出新字符串。","用字符数组原地修改内容，理解字符串结束符与字符读取。","1. 用%100s读字符串，再读取a、b。\n2. 扫描每个非结束字符，等于a时改为b。\n3. 最后用%s输出整个字符串。","只扫描一次，a=b时原样输出。输入000a，替换a为0后必须输出0000，不能当数字输出。","    char s[101],a,b;scanf(\"%100s %c %c\",s,&a,&b);for(int i=0;s[i];i++)if(s[i]==a)s[i]=b;puts(s);"),
 L(24,"长词星碑","输入长度1～100的字符串，由小写字母单词与单个下划线分隔组成，首尾无下划线。输出最长单词及长度；同长选最先出现的单词。","识别分隔符、记录子串起点与长度。","1. 从左到右扫描，每个下划线或末尾结束当前单词。\n2. 仅当当前长度严格大于最佳长度时更新起点与长度。\n3. 依次输出最佳范围的字符，再输出长度。","必须在结尾处理最后一个词；同长时保留较早词，不能使用>=更新。","    char s[101];int st=0,at=0,best=0;scanf(\"%100s\",s);for(int i=0;;i++)if(s[i]=='_'||!s[i]){if(i-st>best){best=i-st;at=st;}st=i+1;if(!s[i])break;}for(int i=at;i<at+best;i++)putchar(s[i]);printf(\" %d\\n\",best);"),
 L(25,"镜面符阵","输入长度1～100的小写字符串。若它是回文输出YES，否则输出NO。","用左右两个下标同时向中心移动，检查对称元素。","1. 左指针从0、右指针从strlen(s)-1开始。\n2. 左小于右时比较字符。\n3. 一旦不相等就记为失败；每次让两端各靠近一步。","最后一个字符在长度减1处，长度处是结束符。一位字符串天然是回文。","    char s[101];int ok=1;scanf(\"%100s\",s);int n=(int)strlen(s);for(int i=0;i<n/2;i++)if(s[i]!=s[n-1-i])ok=0;puts(ok?\"YES\":\"NO\");"),
 L(26,"二维星域","输入r c（各1～6）与r*c个整数（-99～99）。第一行输出每一行的和，第二行输出每一列的和。","学习二维数组、双层循环与不同方向的汇总。","1. 将第i行第j列保存到a[i][j]。\n2. 每行先清零sum，枚举列。\n3. 再每列清零sum，枚举行。\n4. 行数与列数可能不同。","不要把r与c混用；只有一行或一列时也分别输出两行汇总结果。","    int r,c,a[6][6];scanf(\"%d%d\",&r,&c);for(int i=0;i<r;i++)for(int j=0;j<c;j++)scanf(\"%d\",&a[i][j]);for(int i=0;i<r;i++){int s=0;for(int j=0;j<c;j++)s+=a[i][j];printf(\"%d%c\",s,i==r-1?'\\n':' ');}for(int j=0;j<c;j++){int s=0;for(int i=0;i<r;i++)s+=a[i][j];printf(\"%d%c\",s,j==c-1?'\\n':' ');}"),
 L(27,"翻转星图","输入r c（各1～6）与r*c个整数（-99～99），输出转置后的c行r列矩阵。","学习转置对应关系：原来的行变成新的列。","1. 正常按行读入矩阵。\n2. 输出时外层枚举原列j，内层枚举原行i。\n3. 输出a[i][j]；每个原列成为新的一行。","r和c可以不相等；转置不是倒序，也不是旋转90度。","    int r,c,a[6][6];scanf(\"%d%d\",&r,&c);for(int i=0;i<r;i++)for(int j=0;j<c;j++)scanf(\"%d\",&a[i][j]);for(int j=0;j<c;j++)for(int i=0;i<r;i++)printf(\"%d%c\",a[i][j],i==r-1?'\\n':' ');"),
 L(28,"交叉星线","输入n（1～6）与n*n个整数（-99～99），输出主、副对角线上所有元素之和，交点只计一次。","用下标关系表达矩阵中的位置条件，处理重复统计。","1. 主对角线满足i==j，副对角线满足i+j==n-1。\n2. 对每个元素检查两个条件，只要一个成立就加入。\n3. 使用逻辑或可自然避免中心重复。","奇数阶有中心交点；n=1时唯一元素只加一次。不要把两条对角线分别相加后忘记去重。","    int n,x,s=0;scanf(\"%d\",&n);for(int i=0;i<n;i++)for(int j=0;j<n;j++){scanf(\"%d\",&x);if(i==j||i+j==n-1)s+=x;}printf(\"%d\\n\",s);"),
 L(29,"局部星峰","输入r c（各2～6）与r*c个整数（-99～99）。若某格严格大于其存在的上下左右邻格，称为星峰。输出星峰数量。","组合二维遍历、边界判断与多个条件检查。","1. 遍历每个格子，默认它是星峰。\n2. 对存在的相邻格逐一比较。\n3. 任意邻格大于或等于它就不是星峰。\n4. 角点只有两个邻格，边界格不访问越界位置。","严格大于意味着等值邻格会使候选失败；比较前先检查边界，不能读取a[-1][j]。","    int r,c,a[6][6],ans=0;scanf(\"%d%d\",&r,&c);for(int i=0;i<r;i++)for(int j=0;j<c;j++)scanf(\"%d\",&a[i][j]);for(int i=0;i<r;i++)for(int j=0;j<c;j++){int ok=1;if(i>0&&a[i-1][j]>=a[i][j])ok=0;if(i+1<r&&a[i+1][j]>=a[i][j])ok=0;if(j>0&&a[i][j-1]>=a[i][j])ok=0;if(j+1<c&&a[i][j+1]>=a[i][j])ok=0;ans+=ok;}printf(\"%d\\n\",ans);"),
 L(30,"方阵共鸣","输入r k c（各1～4），随后按行输入r*k矩阵A、k*c矩阵B，元素均-10～10。输出乘积矩阵A*B的r行c列结果。","用三层小循环计算矩阵乘积，理解行列配对。","1. A的列数必须等于B的行数k。\n2. 结果位置(i,j)初始为0。\n3. 枚举t，把A[i][t]*B[t][j]加入。\n4. 结果尺寸为r*c。","矩阵乘法不是相同位置元素相乘。每个结果元素需独立清零，不能沿用上一个位置的和。","    int r,k,c,a[4][4],b[4][4];scanf(\"%d%d%d\",&r,&k,&c);for(int i=0;i<r;i++)for(int t=0;t<k;t++)scanf(\"%d\",&a[i][t]);for(int t=0;t<k;t++)for(int j=0;j<c;j++)scanf(\"%d\",&b[t][j]);for(int i=0;i<r;i++)for(int j=0;j<c;j++){int s=0;for(int t=0;t<k;t++)s+=a[i][t]*b[t][j];printf(\"%d%c\",s,j==c-1?'\\n':' ');}")
 };
