 string[] steps={"1. 从最高次系数开始。\n2. 每读下一项，令value=value*x+coefficient。\n3. long long保存累计值，n=0也要读取常数项。", "1. 用数组标记合数。\n2. 从2开始，把它的倍数标记。\n3. 扫描[l,r]累计未标记的数量和数值，排除0与1。", "1. 将'0'到'9'和'A'到'F'转为对应数值。\n2. 依次执行value=value*b+digit。\n3. 用unsigned long long配合%llu输出。", "1. 枚举文本的每个可能起点。\n2. 逐字符比较是否完整匹配模式。\n3. 保存匹配数量与1基起点，允许重叠，未匹配时第二行输出0。数据小，无需KMP。", "1. 枚举每个字符中心以及两个字符间的中心。\n2. 两边字符相等且未越界就继续扩展。\n3. 记录最长的连续长度。", "1. 先按左端点排序。\n2. 新区间与最后区间重叠时扩大右端点。\n3. 不重叠才新开一段，等端点也要合并。", "1. 对每个位置向右扫描。\n2. 找到第一个严格更大值就停止。\n3. 输出其1基下标，找不到为0；本题小规模允许双循环，无需单调栈。", "1. 枚举每个长度k的窗口。\n2. 窗口内逐项比较得到最大值。\n3. 窗口右移一格并继续；小规模双循环足够，无需单调队列。", "1. 每次区间查询直接枚举[l,r]。\n2. 一边累加普通和，一边乘上从1开始的相对权重。\n3. 使用long long输出两个和；无需推导加权前缀公式。", "1. 用两层循环枚举i<j。\n2. 当a[i]>a[j]计数加一。\n3. 相等值不计，n≤150直接枚举即可，无需归并排序。", "1. 用parent记录每个点的父节点。\n2. 查询根时反复沿parent向上。\n3. 合并让一个根指向另一个；查询比较两者根是否相同。", "1. result初始为1%m。\n2. 指数为奇数时把当前底数乘入答案。\n3. 底数平方取模，指数除2，循环直到0。乘法前使用long long。", "1. dp[j]表示容量j内的最高价值。\n2. 每件物品只用一次，所以容量从大向小更新。\n3. 比较不取与取当前物品两种情况。", "1. dp[i][j]表示两字符串前i、j项的最长公共子序列长度。\n2. 字符相同取左上加1，否则取上与左较大值。\n3. 第0行第0列均为0，答案是右下角。"};
 for(int i=0;i<old.Length;i++){int n=31+i;var source=LegacyChallengeBank.Levels[old[i]-1];a.Add(new ChallengeLevel{Number=n,Problem=new Problem(100+n,source.Problem.Title,"暗域 · "+Chapters[(n-1)/10],source.Problem.Statement,"优先采用提示中的直观解法。",source.Problem.Reference),Learning=Lesson(n,"从小规模可验证解法开始，掌握"+source.Problem.Title+"的状态与循环。",steps[i],"检查最小输入、相同值、全区间和无结果情况。先根据样例手算中间状态，再核对数据类型与输出格式。")});}
