 var dynamic=LegacyChallengeBank.Levels[39];a.Add(new ChallengeLevel{Number=46,Problem=new Problem(146,"巡航账本 · 小项目","暗域 · 深空试炼",dynamic.Problem.Statement,"小规模可直接更新和查询数组。",C("    int n,q;long long a[81];scanf(\"%d%d\",&n,&q);for(int i=1;i<=n;i++)scanf(\"%lld\",a+i);while(q--){char op;int l,r;scanf(\" %c%d%d\",&op,&l,&r);if(op=='A')a[l]+=r;else{long long s=0;for(int i=l;i<=r;i++)s+=a[i];printf(\"%lld\\n\",s);}}")),Learning=Lesson(46,"以数组管理可修改的账本，组合命令解析、更新和查询。","1. A命令修改指定位置。\n2. Q命令直接循环求区间和。\n3. 每次查询使用最新状态。数据小，不要求树状数组。","命令前空白需跳过；delta可以为负数；读入的两个整数在不同命令下含义不同。")});
 AddOrdinary(a,47,88,"星港成绩站 · 项目","1. 为每个id维护是否存在与成绩。\n2. 增改、查询、删除分别处理。\n3. 统计仅遍历存在记录；排名按成绩降序，同分编号升序。\n4. 先完成前三种命令，再补统计和排序，空集平均为0。");
