 AddOrdinary(a,49,90,"星舰图书馆 · 项目","1. 保存图书余量、用户总借阅数和用户-图书二维关系。\n2. 先验证所有借阅条件，再统一更新三组状态。\n3. 还书要求关系存在，成功后同步恢复状态。\n4. 用同一用户连续借还、库存耗尽和重复借阅验证一致性。");
 var last=LegacyChallengeBank.Levels[49];a.Add(new ChallengeLevel{Number=50,Problem=new Problem(150,last.Problem.Title,"暗域 · 深空试炼",last.Problem.Statement,"把库存与快照拆开存储，逐条实现命令。",last.Problem.Reference),Learning=Lesson(50,"综合命令处理、数组复制、库存校验和历史快照。","1. 先实现ADD/SELL/GET/TOTAL。\n2. TOP并列时保留较小id。\n3. SNAP复制整份库存到新的二维数组行，编号递增。\n4. LOAD复制回当前库存，不修改原快照。\n5. 最后测试保存、修改、恢复、再次修改、再次恢复的完整流程。","快照必须复制内容，不能让当前库存与历史共用可修改数据；失败SELL不扣库存；空库存TOP为1 0。")});
