 a[33].Problem.Reference=C("    char s[201],p[41];int at[200],c=0;scanf(\"%200s%40s\",s,p);int n=(int)strlen(s),m=(int)strlen(p);for(int i=0;i+m<=n;i++){int ok=1;for(int j=0;j<m;j++)if(s[i+j]!=p[j])ok=0;if(ok)at[c++]=i+1;}printf(\"%d\\n\",c);if(!c)puts(\"0\");else for(int i=0;i<c;i++)printf(\"%d%c\",at[i],i==c-1?'\\n':' ');");
 a[36].Problem.Reference=C("    int n,a[100];scanf(\"%d\",&n);for(int i=0;i<n;i++)scanf(\"%d\",a+i);for(int i=0;i<n;i++){int ans=0;for(int j=i+1;j<n;j++)if(a[j]>a[i]){ans=j+1;break;}printf(\"%d%c\",ans,i==n-1?'\\n':' ');}");
