 static void AddOrdinary(List<ChallengeLevel> a,int n,int id,string title,string steps){var p=Bank.All().First(x=>x.Id==id);a.Add(new ChallengeLevel{Number=n,Problem=new Problem(100+n,title,"暗域 · "+Chapters[(n-1)/10],p.Statement,p.Hint,p.Reference),Learning=Lesson(n,p.Hint,steps,"数组大小要覆盖最大id；只在条件满足时更新状态，操作失败时保持原状。注意题目规定的输出精度与空数据情况。")});}
 static bool Prime(int n){return n>=2&&!Enumerable.Range(2,Math.Max(0,(int)Math.Sqrt(n)-1)).Any(d=>n%d==0);}
 static string J<T>(IEnumerable<T> values){return string.Join(" ",values.Select(x=>Convert.ToString(x,CultureInfo.InvariantCulture)).ToArray());}
 public static List<TestCase> Tests(int id,int seed){var r=new Random(seed);var list=new List<TestCase>();for(int i=0;i<8;i++)list.Add(Generate(id,r,i));for(int i=0;i<20;i++)list.Add(Generate(id,r,-1));return list;}
 public static TestCase Generate(int id,Random r,int e){int k=id-100;if(k<1||k>50)throw new ArgumentOutOfRangeException("id");bool edge=e>=0;string input="",expected="";
  if(k>=31){int[] old={16,9,12,13,14,5,6,7,1,21,23,20,36,34};if(k<=44)return LegacyChallengeBank.Generate(100+old[k-31],r,e);if(k==45)return Bank.Generate(87,r,e);if(k==46)return LegacyChallengeBank.Generate(140,r,e);if(k<=49)return Bank.Generate(k+41,r,e);return LegacyChallengeBank.Generate(150,r,e);}
  if(k<=10){int[] edges={0,1,9,10,100,101,999999999,1000000000};int n=edge?edges[e]:r.Next(0,1000000001);input=n+"\n";if(k==1)expected=n.ToString().Sum(c=>c-'0').ToString();else if(k==2){string s=n.ToString();expected=s.Count(c=>(c-'0')%2==1)+" "+s.Count(c=>(c-'0')%2==0);}else if(k==3){n=edge?new[]{1,2,6,16,97,100,9999,10000}[e]:r.Next(1,10001);input=n+"\n";expected=Enumerable.Range(1,n).Where(d=>n%d==0).Sum().ToString();}else if(k==4){n=edge?new[]{1,2,3,4,9,10,997,1000}[e]:r.Next(1,1001);input=n+"\n";expected=Enumerable.Range(1,n).Count(Prime).ToString();}else if(k==5){n=edge?new[]{0,1,2,3,255,256,65534,65535}[e]:r.Next(65536);input=n+"\n";expected=Convert.ToString(n,2).Count(c=>c=='1').ToString();}else if(k==6){int x=edge?new[]{1,2,7,12,10000,9999,10,36}[e]:r.Next(1,10001),y=edge?new[]{1,4,13,18,10000,10000,1,48}[e]:r.Next(1,10001),g=Enumerable.Range(1,Math.Min(x,y)).Last(d=>x%d==0&&y%d==0);input=x+" "+y+"\n";expected=g+" "+(x/g*y);}else if(k==7){n=edge?new[]{0,1,11,10,101,12321,999999,1000000}[e]:r.Next(1000001);input=n+"\n";string s=n.ToString();expected=s==new string(s.Reverse().ToArray())?"YES":"NO";}else if(k==9){n=edge?new[]{1,2,3,4,10,20,39,40}[e]:r.Next(1,41);long a=1,b=1,s=0;for(int i=0;i<n;i++){s+=a;long t=a+b;a=b;b=t;}input=n+"\n";expected=s.ToString();}else if(k==8||k==10){int l=edge?new[]{1,1,2,4,11,100,499,500}[e]:r.Next(1,501),h=edge?new[]{1,2,2,10,13,500,500,500}[e]:r.Next(l,501);var range=Enumerable.Range(l,h-l+1);input=l+" "+h+"\n";expected=k==8?range.Count(Prime)+" "+range.Where(Prime).Sum():range.Count(Prime)+" "+range.Count(x=>(int)Math.Sqrt(x)*(int)Math.Sqrt(x)==x)+" "+range.Where(x=>x%2!=0).Sum();}}
  else if(k<=20){int n=edge?(e==0?1:e==1?50:8):r.Next(1,51);int[] a=Enumerable.Range(0,n).Select(i=>edge?(e==1?1000:e==2?-1000:e==3?0:e==4?i-4:e==5?4-i:e==6?(i%2==0?-3:4):7):r.Next(-1000,1001)).ToArray();input=n+"\n"+J(a)+"\n";
