  else if(k<=25){string pool=k==21?"ABCxyz019!?":k==23?"ab019":"abc";int n=edge?(e==0?1:e==1?100:12):r.Next(1,101);string s=new string(Enumerable.Range(0,n).Select(i=>edge&&e==2?'a':pool[r.Next(pool.Length)]).ToArray());if(k==23&&edge)s=new[]{"0","00000000000000000000","aaaa","a0a","999999","a1b1","Abc","000a"}[e];if(k==24){int words=edge?e+1:r.Next(1,9);s=string.Join("_",Enumerable.Range(0,words).Select(i=>new string(Enumerable.Range(0,r.Next(1,10)).Select(j=>(char)('a'+r.Next(4))).ToArray())).ToArray());}if(k==25&&edge)s=new[]{"a",new string('a',100),"aba","abba","abca","aaab","abcba","ab"}[e];input=s+"\n";
